@@ -1,8 +1,10 @@
 import { greet } from './greet.ts';

-const arg = process.argv[2];
-if (arg === '--help') {
-  console.log('usage: greet [name]');
+const args = process.argv.slice(2);
+if (args.includes('--help')) {
+  console.log('usage: greet [name] [--shout]');
 } else {
-  console.log(greet(arg ?? ''));
